terraform {
  required_providers { aws = { source = "hashicorp/aws", version = "~> 5.0" } }
}
provider "aws" { region = var.region }
variable "region" { default = "us-east-1" }

data "aws_vpc" "default" { default = true }
data "aws_subnets" "default" {
  filter { name = "vpc-id"  values = [data.aws_vpc.default.id] }
}
data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["099720109477"] # Canonical
  filter { name = "name" values = ["ubuntu/images/hvm-ssd-gp3/ubuntu-noble-24.04-amd64-server-*"] }
}

resource "aws_iam_role" "ssm" {
  name = "lab-vm-ssm"
  assume_role_policy = jsonencode({ Version = "2012-10-17", Statement = [{ Effect = "Allow", Principal = { Service = "ec2.amazonaws.com" }, Action = "sts:AssumeRole" }] })
}
resource "aws_iam_role_policy_attachment" "ssm" {
  role       = aws_iam_role.ssm.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}
resource "aws_iam_instance_profile" "ssm" { name = "lab-vm-ssm"  role = aws_iam_role.ssm.name }

resource "aws_security_group" "lab" {
  name   = "lab-vms"
  vpc_id = data.aws_vpc.default.id
  ingress { from_port = 0  to_port = 0  protocol = "-1"  self = true }
  egress  { from_port = 0  to_port = 0  protocol = "-1"  cidr_blocks = ["0.0.0.0/0"] }
}

resource "aws_instance" "vm" {
  count                                = 2
  ami                                  = data.aws_ami.ubuntu.id
  instance_type                        = "t3.large"
  subnet_id                            = data.aws_subnets.default.ids[0]   # same subnet for both
  vpc_security_group_ids               = [aws_security_group.lab.id]
  iam_instance_profile                 = aws_iam_instance_profile.ssm.name
  instance_initiated_shutdown_behavior = "terminate"
  root_block_device { volume_size = 40  volume_type = "gp3" }
  user_data = "#!/bin/bash\nshutdown -h +360\n"   # safety net: dies after 6 h
  tags = { Name = "lab-vm-${count.index}" }
}
output "ids"         { value = aws_instance.vm[*].id }
output "private_ips" { value = aws_instance.vm[*].private_ip }

terraform {
  required_providers { aws = { source = "hashicorp/aws", version = "~> 5.0" } }
}
provider "aws" { region = var.region }
variable "region"        { default = "us-east-1" }
variable "instance_type" { default = "g4dn.xlarge" }   # g5.xlarge | g4dn.12xlarge | g5.12xlarge

data "aws_vpc" "default" { default = true }
data "aws_subnets" "default" {
  filter { name = "vpc-id"  values = [data.aws_vpc.default.id] }
}
data "aws_ami" "dlami" {
  most_recent = true
  owners      = ["amazon"]
  filter { name = "name" values = ["Deep Learning Base OSS Nvidia Driver GPU AMI (Ubuntu 22.04)*"] }
}

resource "aws_iam_role" "ssm" {
  name = "lab-gpu-ssm"
  assume_role_policy = jsonencode({ Version = "2012-10-17", Statement = [{ Effect = "Allow", Principal = { Service = "ec2.amazonaws.com" }, Action = "sts:AssumeRole" }] })
}
resource "aws_iam_role_policy_attachment" "ssm" {
  role       = aws_iam_role.ssm.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}
resource "aws_iam_instance_profile" "ssm" { name = "lab-gpu-ssm"  role = aws_iam_role.ssm.name }

resource "aws_security_group" "gpu" {
  name   = "lab-gpu"
  vpc_id = data.aws_vpc.default.id
  ingress { from_port = 0  to_port = 0  protocol = "-1"  self = true }
  egress  { from_port = 0  to_port = 0  protocol = "-1"  cidr_blocks = ["0.0.0.0/0"] }
}

resource "aws_instance" "gpu" {
  ami                                  = data.aws_ami.dlami.id
  instance_type                        = var.instance_type
  subnet_id                            = data.aws_subnets.default.ids[0]
  vpc_security_group_ids               = [aws_security_group.gpu.id]
  iam_instance_profile                 = aws_iam_instance_profile.ssm.name
  instance_initiated_shutdown_behavior = "terminate"
  instance_market_options {
    market_type = "spot"
    spot_options { spot_instance_type = "one-time"  instance_interruption_behavior = "terminate" }
  }
  root_block_device { volume_size = 150  volume_type = "gp3" }
  user_data = "#!/bin/bash\nshutdown -h +240\n"   # safety net: dies after 4 h
  tags = { Name = "lab-gpu" }
}
output "id" { value = aws_instance.gpu.id }

resource "aws_placement_group" "pg" { name = "lab-efa"  strategy = "cluster" }

resource "aws_security_group_rule" "self_egress" {
  type = "egress"  from_port = 0  to_port = 0  protocol = "-1"
  security_group_id = aws_security_group.gpu.id  source_security_group_id = aws_security_group.gpu.id
}

resource "aws_instance" "gpu" {
  count           = 2
  ami             = data.aws_ami.dlami.id
  instance_type   = "g4dn.12xlarge"
  placement_group = aws_placement_group.pg.id
  iam_instance_profile = aws_iam_instance_profile.ssm.name
  network_interface {
    device_index         = 0
    network_interface_id = aws_network_interface.efa[count.index].id
  }
  root_block_device { volume_size = 150  volume_type = "gp3" }
  user_data = "#!/bin/bash\nshutdown -h +180\n"
  instance_initiated_shutdown_behavior = "terminate"
  tags = { Name = "lab-efa-${count.index}" }
}
resource "aws_network_interface" "efa" {
  count           = 2
  subnet_id       = data.aws_subnets.default.ids[0]
  security_groups = [aws_security_group.gpu.id]
  interface_type  = "efa"
}
output "ids" { value = aws_instance.gpu[*].id }
output "ips" { value = aws_network_interface.efa[*].private_ip }
